CREATE TABLE concept_scheme (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    agency_id VARCHAR(100) NOT NULL,
    artefact_id VARCHAR(100) NOT NULL,
    version VARCHAR(20) NOT NULL,
    name VARCHAR(255) NOT NULL,
    UNIQUE (agency_id, artefact_id, version)
);

-- GENERATED BY DEFAULT (not ALWAYS): Spring Data JDBC re-inserts the whole
-- child collection, including previously persisted rows, on every aggregate
-- save, so it must be allowed to write back an existing id.
CREATE TABLE concept (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    concept_scheme_id BIGINT NOT NULL REFERENCES concept_scheme (id) ON DELETE CASCADE,
    code VARCHAR(100) NOT NULL,
    name VARCHAR(255) NOT NULL,
    UNIQUE (concept_scheme_id, code)
);

CREATE TABLE codelist (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    agency_id VARCHAR(100) NOT NULL,
    artefact_id VARCHAR(100) NOT NULL,
    version VARCHAR(20) NOT NULL,
    name VARCHAR(255) NOT NULL,
    UNIQUE (agency_id, artefact_id, version)
);

CREATE TABLE code (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codelist_id BIGINT NOT NULL REFERENCES codelist (id) ON DELETE CASCADE,
    code VARCHAR(100) NOT NULL,
    name VARCHAR(255) NOT NULL,
    UNIQUE (codelist_id, code)
);

CREATE TABLE data_structure_definition (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    agency_id VARCHAR(100) NOT NULL,
    artefact_id VARCHAR(100) NOT NULL,
    version VARCHAR(20) NOT NULL,
    name VARCHAR(255) NOT NULL,
    UNIQUE (agency_id, artefact_id, version)
);

CREATE TABLE dsd_dimension (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dsd_id BIGINT NOT NULL REFERENCES data_structure_definition (id) ON DELETE CASCADE,
    position INT NOT NULL,
    concept_id BIGINT NOT NULL REFERENCES concept (id),
    codelist_id BIGINT REFERENCES codelist (id),
    data_type VARCHAR(20) NOT NULL CHECK (data_type IN ('STRING', 'NUMBER', 'DATE')),
    UNIQUE (dsd_id, position)
);

CREATE TABLE dsd_measure (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dsd_id BIGINT NOT NULL REFERENCES data_structure_definition (id) ON DELETE CASCADE,
    concept_id BIGINT NOT NULL REFERENCES concept (id),
    data_type VARCHAR(20) NOT NULL CHECK (data_type IN ('STRING', 'NUMBER', 'DATE'))
);

CREATE TABLE category_scheme (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    agency_id VARCHAR(100) NOT NULL,
    artefact_id VARCHAR(100) NOT NULL,
    version VARCHAR(20) NOT NULL,
    name VARCHAR(255) NOT NULL,
    UNIQUE (agency_id, artefact_id, version)
);

CREATE TABLE category (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category_scheme_id BIGINT NOT NULL REFERENCES category_scheme (id) ON DELETE CASCADE,
    -- deferred: on each aggregate save, Spring Data JDBC re-inserts the whole
    -- category set in one batch without guaranteeing parent-before-child order
    parent_category_id BIGINT REFERENCES category (id) DEFERRABLE INITIALLY DEFERRED,
    code VARCHAR(100) NOT NULL,
    name VARCHAR(255) NOT NULL,
    UNIQUE (category_scheme_id, code)
);

CREATE TABLE dataflow (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    agency_id VARCHAR(100) NOT NULL,
    artefact_id VARCHAR(100) NOT NULL,
    version VARCHAR(20) NOT NULL,
    name VARCHAR(255) NOT NULL,
    dsd_id BIGINT NOT NULL REFERENCES data_structure_definition (id),
    UNIQUE (agency_id, artefact_id, version)
);

CREATE TABLE categorisation (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    dataflow_id BIGINT NOT NULL REFERENCES dataflow (id) ON DELETE CASCADE,
    category_id BIGINT NOT NULL REFERENCES category (id)
);
